import json
def R(id,title,desc,por,serv,ing,steps,hints,fc):
    n=lambda l:[[None,t] for t in l]
    return {"id":id,"translations":{"fr":{"title":title,"description":desc,"portions":por,"serving_size":serv,"ingredients":n(ing),"steps":n(steps),"hints":n(hints),"food_choices":fc}}}
o=[]
o.append(R(2757,"Dîner facile au poulet et aux pâtes",
"« Facile » est un mot que la plupart d'entre nous aiment voir sur une nouvelle recette. Le poulet et les pâtes sont deux aliments qui s'associent pour faire un repas savoureux. Michael, patient dialysé DaVita, a imaginé cette délicieuse recette de dîner facile au poulet et aux pâtes en ajoutant des poivrons rouges, des courgettes et de la vinaigrette italienne pauvre en sodium au poulet et aux pâtes pour obtenir un repas relevé et copieux. Ce repas complet en un seul plat, proposé par Mary Anne, diététicienne rénale DaVita en Californie, est facile à préparer, adapté aux reins et appétissant.",
"2","1 tasse de pâtes, 2-1/2 oz de poulet, 2/3 tasse de légumes",
["1 cuillère à soupe d'huile d'olive","1/2 tasse de poivron rouge, en tranches","1 tasse de courgette, en rondelles","2 tasses de pâtes cuites, de la forme de votre choix","5 onces de blanc de poulet cuit","3 cuillères à soupe de vinaigrette italienne pauvre en sodium"],
["Dans une poêle antiadhésive, chauffez l'huile d'olive et faites sauter les courgettes et les poivrons jusqu'à ce qu'ils soient tendres mais encore croquants. Déposez-les dans une assiette.","Coupez le poulet en lanières.","Réchauffez les pâtes cuites et les lanières de poulet au micro-ondes, dans des plats séparés.","Mélangez les pâtes avec la vinaigrette italienne. Garnissez de lanières de poulet et de légumes sautés."],
["Préparez certains éléments à l'avance pour en faire un dîner rapide. Faites cuire une grande casserole de pâtes, égouttez-les et réfrigérez-les pour les utiliser dans cette recette et dans d'autres plats de pâtes.","Faites griller au four ou au barbecue une livre de blancs ou de cuisses de poulet. Réfrigérez et utilisez-les pour cette recette et d'autres plats de poulet pendant la semaine.","Si vous devez suivre un régime pauvre en protéines, ajustez la portion de poulet dans ce plat."],
["3 viande","2-1/2 féculent","1 légume, teneur moyenne en potassium"]))
o.append(R(2761,"Crème fouettée",
"Essayez de préparer la crème fouettée à la maison pour éviter les additifs phosphatés et autres ingrédients indésirables. C'est si facile que vous n'achèterez peut-être plus jamais de garniture fouettée toute prête.",
"16","2 cuillères à soupe",
["1 tasse de crème à fouetter (crème épaisse)","1/2 cuillère à café d'extrait de vanille","2 cuillères à soupe de sucre ou d'édulcorant de votre choix"],
["Placez un bol d'une capacité d'un quart de gallon et les fouets d'un batteur à main au congélateur pendant 15 à 20 minutes.","Versez la crème à fouetter, l'extrait de vanille et le sucre dans le bol refroidi. Commencez à battre à basse vitesse. Lorsque la crème commence à mousser, battez à haute vitesse jusqu'à l'obtention de pics fermes. Veillez à ne pas trop battre."],
["Vous pouvez utiliser l'édulcorant de votre choix, selon votre goût, dans la recette.","Utilisez-la dans les recettes qui demandent une garniture de crème fouettée ou de dessert glacé Cool Whip®. La crème fouettée maison ne contient pas d'additifs phosphatés."],
["1 matière grasse"]))
o.append(R(2764,"Bento riche en protéines",
"Ce bento est un repas du midi complet et facile.",
"2","1 boîte bento",
["Une boîte de 4,5 onces de thon sans sel ajouté, conservé dans l'eau","1 petite branche de céleri","2 cuillères à soupe d'oignon rouge","1 cuillère à soupe de mayonnaise","1 cuillère à café d'ail en poudre","1 cuillère à café d'aneth séché","1/2 cuillère à café d'oignon en poudre","10 mini-carottes","1 mini-concombre","1 pomme","2 œufs durs","2 galettes de riz"],
["Égouttez le thon et placez-le dans un petit saladier. Coupez le céleri et l'oignon rouge en petits dés.","Ajoutez la mayonnaise, le céleri et l'oignon en dés ainsi que les épices au thon. Mélangez bien.","Pelez les concombres et coupez-les en bâtonnets. Coupez la pomme en fines tranches. Si vous ne trouvez pas de mini-concombres, utilisez 5 tranches d'un concombre moyen pour chaque boîte.","Utilisez deux boîtes bento. Répartissez dans les boîtes la moitié du mélange de thon, la moitié des carottes et la moitié du concombre. Coupez les œufs en deux et ajoutez 1 œuf et 1 galette de riz dans chaque boîte."],
["Pour réussir des œufs durs : placez les œufs dans une casserole et couvrez-les d'eau. Laissez l'eau bouillir 5 minutes, éteignez le feu et laissez les œufs dans l'eau 10 minutes. Rincez-les à l'eau froide et écalez-les immédiatement.","Au lieu des galettes de riz, vous pouvez aussi utiliser des crackers multicéréales ou des galettes de maïs. Respectez la portion indiquée sur l'emballage et recherchez des variétés à plus faible teneur en sodium.","Ce bento est un repas complet. Sa teneur en potassium est plus élevée que celle d'un plat principal habituel, mais il est considéré comme un repas complet et acceptable dans une alimentation adaptée aux reins. La plus grande partie du potassium provient d'aliments frais et naturels."],
["2-1/2 protéines","1 légume, teneur moyenne en potassium","1/2 fruit, faible teneur en potassium"]))
o.append(R(2767,"Sauce mojo",
"Du piment jalapeño, du jus d'agrumes, de la coriandre, du cumin et de l'origan sont associés à l'huile d'olive pour préparer cette célèbre sauce mojo cubaine. Essayez-la avec des œufs ou des plats de viande.",
"12","2 cuillères à soupe",
["1 piment jalapeño","1/2 tasse d'huile d'olive","1/2 tasse de jus de lime","1/3 tasse de jus d'orange","8 gousses d'ail","1 cuillère à café d'origan séché","1/4 cuillère à café de cumin","1/2 tasse de coriandre fraîche"],
["Retirez les graines du piment jalapeño.","Mettez les ingrédients dans un mixeur ou un robot culinaire et mixez jusqu'à obtenir une texture lisse.","Conservez la sauce au réfrigérateur dans un récipient couvert pendant une semaine au maximum."],
["Vous pouvez remplacer la coriandre par du persil si vous préférez. Remplacez le jalapeño par le piment de votre choix.","Ajustez le cumin et l'origan à votre goût.","Utilisez la sauce mojo comme marinade ou comme sauce d'accompagnement. Essayez-la avec la recette d'Arroz a la Cubano de Sylvia."],
["2 matière grasse"]))
o.append(R(2768,"Steak aux poivrons",
"Le steak aux poivrons est adapté aux reins et facile à préparer grâce aux instructions pas à pas de Carol. Simple, vif et sensationnel !",
"6","1 tasse",
["3 livres de steak de bœuf mince, coupé en lanières","2 cuillères à soupe d'huile d'olive","1 oignon moyen, haché finement","2 tasses de poivrons verts, hachés finement","1 tasse de carottes, en fines rondelles","1/2 tasse de céleri, haché","1-1/4 tasse d'eau","1 sachet de préparation pour sauce brune"],
["Dans une grande poêle, faites dorer la viande dans l'huile à feu moyen-vif.","Ajoutez tous les légumes et 1/4 tasse d'eau. Couvrez la poêle et laissez cuire en remuant de temps en temps, jusqu'à ce que les légumes soient tendres.","Ajoutez la préparation pour sauce brune et 1 tasse d'eau.","Remuez à feu moyen jusqu'à ce que la sauce épaississe."],
["Comparez les marques et achetez la préparation pour sauce brune la plus pauvre en sodium."],
["4 viande","1-1/2 légume, teneur moyenne en potassium"]))
o.append(R(2769,"Pain à la citrouille des pionniers",
"Cette recette donne 3 pains à la citrouille des pionniers. Gardez-en un et partagez ou congelez les autres.",
"30 (3 pains)","1/10 de tranche d'un pain",
["3-1/2 tasses de farine blanche tout usage","3 tasses de sucre","3 cuillères à café de bicarbonate de soude","1 cuillère à café de sel","1 cuillère à café de cannelle moulue","1 cuillère à café de muscade moulue","1 tasse d'huile","2/3 tasse d'eau","4 œufs","une boîte de 15 onces de purée de citrouille"],
["Préchauffez le four à 350° F.","Mélangez les ingrédients secs dans un grand bol. Ajoutez l'huile, l'eau, les œufs et la citrouille. Remuez jusqu'à ce que le tout soit bien mélangé. Ajoutez des noix, si désiré.","Versez la pâte dans des moules à pain légèrement vaporisés d'aérosol de cuisson antiadhésif.","Pour 3 pains de taille normale, faites cuire pendant 1 heure ou jusqu'à ce qu'un cure-dent inséré au centre en ressorte propre. Pour 6 mini-pains, faites cuire 45 minutes.","Laissez refroidir les pains dans leurs moules sur une grille pendant 10 minutes, puis démoulez-les, remettez-les à l'endroit et poursuivez le refroidissement. Enveloppez-les dans du papier d'aluminium une fois complètement refroidis."],
["Une tasse de pacanes hachées (facultatif) ajoutée à cette recette fait passer le potassium à 70 milligrammes et le phosphore à 40 milligrammes.","Une tasse de noix (facultatif) ajoutée à cette recette fait passer le potassium à 86 milligrammes et le phosphore à 57 milligrammes.","Préparez les pains à l'avance et congelez-les jusqu'au moment de les partager ou de les savourer."],
["2 féculent","1 matière grasse"]))
o.append(R(2770,"Salade de légumes du jardin",
"Les diététiciens rénaux DaVita du Minnesota partagent certaines de leurs recettes régionales préférées, adaptées à l'alimentation des personnes dialysées. En limitant le phosphore, le potassium et le sodium, les patients dialysés peuvent savourer une délicieuse salade de légumes du jardin.",
"1","1-3/4 tasse",
["1 tasse de laitue","1/4 de concombre moyen","4 mini-carottes","1/4 tasse de fleurettes de brocoli","2 cuillères à soupe de vinaigre balsamique","1 cuillère à café d'huile d'olive"],
["Nettoyez, lavez et séchez tous les légumes.","Hachez grossièrement la laitue et placez-la dans un saladier.","Coupez le concombre en rondelles et disposez-les sur la laitue.","Hachez ou râpez les 4 mini-carottes et mettez-les dans le saladier.","Coupez ou séparez les fleurettes de brocoli en petits morceaux.","Mélangez le vinaigre balsamique et l'huile d'olive et versez sur la salade.","Mélangez délicatement et servez."],
["Vous pouvez remplacer le vinaigre balsamique et l'huile d'olive par de la vinaigrette italienne pauvre en sodium ou une autre vinaigrette de votre choix.","Vous pouvez ajouter un blanc de poulet cuit pour augmenter l'apport en protéines."],
["2 légume, teneur moyenne en potassium","1 matière grasse"]))
o.append(R(2771,"Arroz con leche (riz au lait)",
"Transformez du simple riz blanc en un délicieux dessert adapté aux reins grâce à la recette d'arroz con leche de Melisa, diététicienne rénale. En remplaçant le lait par un substitut pauvre en potassium et en phosphore, les patients dialysés peuvent se resservir sans dépasser les objectifs de leur régime rénal.",
"6","1/2 tasse",
["1 tasse de riz blanc, cru","2 tasses de lait d'amande non sucré","2 cuillères à soupe de raisins secs","1/4 tasse de sucre cristallisé","1/4 cuillère à café de cannelle","1 cuillère à café d'extrait de vanille"],
["Rincez le riz à l'eau du robinet, puis égouttez-le.","Mettez le riz et 1 tasse d'eau dans une casserole moyenne. Portez à ébullition, couvrez et laissez cuire 10 minutes.","Retirez le couvercle et incorporez le lait d'amande et les raisins secs. Couvrez de nouveau et laissez bouillir 10 minutes ou jusqu'à ce que le riz soit bien cuit. (Le riz aura une consistance liquide ; tout le liquide ne s'évaporera pas.)","Lorsque le riz est cuit, retirez-le du feu et incorporez le sucre (ou l'édulcorant), la cannelle et la vanille. Mélangez bien et servez tiède.","Réfrigérez les restes."],
["Cherchez du lait d'amande non réfrigéré et choisissez une marque sans additifs phosphatés.","Les raisins secs sont facultatifs. La portion doit être limitée en raison de leur teneur supplémentaire en potassium.","La recette a été révisée pour supprimer la crème non laitière. Le sucre a été réduit de 1/2 tasse à 1/4 tasse. Ajustez la quantité si vous aimez un dessert plus sucré.","Le choix de glucides est de 2 lorsque la recette est préparée avec un substitut de sucre au lieu de sucre. Les calories passent à 195 et les glucides à 27 grammes par portion."],
["1 féculent","1/2 substitut de lait","1 calorie élevée"]))
o.append(R(2773,"Tarte à la lime de Floride (Key lime pie)",
"Une croûte de biscuits Graham, du jus de lime, du lait concentré sucré et de la garniture fouettée sont les ingrédients de la tarte à la lime de Floride, une gourmandise adaptée aux reins proposée par l'équipe de diététiciens DaVita.",
"8","1/8 de tarte",
["5 cuillères à soupe de beurre non salé","1-1/4 tasse de miettes de biscuits Graham","1/4 tasse de sucre cristallisé","1/3 tasse de jus de lime","14 onces de lait concentré sucré en conserve","1 tasse de crème à fouetter (crème épaisse)"],
["Préchauffez le four à 350° F.","Faites fondre le beurre et ajoutez les miettes de biscuits Graham et le sucre ; mélangez bien. Réservez 1 à 2 cuillères à soupe du mélange de miettes pour saupoudrer le dessus de la tarte.","Pressez dans un moule à tarte de 9 pouces. Faites cuire 5 minutes. Sortez du four et laissez refroidir.","Dans un bol, mélangez soigneusement le jus de lime et le lait concentré.","Avec un bol et des fouets refroidis, fouettez la crème épaisse au batteur à main jusqu'à l'obtention de pics fermes. Incorporez délicatement la crème au mélange de lait concentré.","Versez le mélange dans la croûte et saupoudrez du reste de miettes.","Réfrigérez jusqu'au moment de servir."],
["Décorez de zeste de lime si désiré.","Cette tarte peut être congelée pour un dessert glacé.","Ce dessert très riche constitue un merveilleux plaisir occasionnel. Il n'est pas recommandé aux personnes diabétiques en raison de sa forte teneur en glucides et en matières grasses."],
["1 féculent","1 calorie élevée","1 lait","3 matière grasse"]))
o.append(R(2774,"Samosa",
"Savourez les saveurs du creuset américain avec Tahseen, diététicienne rénale DaVita en Floride. Après avoir vécu aux quatre coins du monde et goûté des plats de nombreuses cultures, Tahseen partage ses recettes de cinq-épices chinois, venu de Chine, et de garam masala, venu d'Inde. Aujourd'hui, elle partage une recette de samosa adaptée aux reins, une collation populaire en Inde qui contient du garam masala pour un assaisonnement pauvre en sodium.",
"24","1 samosa",
["1/4 tasse d'oignon","1 cuillère à café de gingembre frais","2 cuillères à soupe de coriandre fraîche","1/2 tasse de petits pois verts surgelés","3 cuillères à soupe d'huile de canola, plus de l'huile pour la friture","1 cuillère à soupe de coriandre en poudre","1/4 cuillère à café de piment de Cayenne","1 cuillère à café de garam masala","1 livre de bœuf haché","24 feuilles de pâte pour rouleaux de printemps (1 paquet)","2 cuillères à soupe de farine blanche tout usage","2 cuillères à café d'eau"],
["Hachez l'oignon ; hachez finement le gingembre et la coriandre. Sortez les petits pois pour les décongeler.","Chauffez 3 cuillères à soupe d'huile dans une grande poêle à feu moyen. Ajoutez l'oignon, le gingembre, la coriandre, le piment et le garam masala.","Ajoutez le bœuf haché et faites cuire jusqu'à ce qu'il ne soit plus rose. Égouttez la graisse.","Ajoutez les petits pois et faites cuire jusqu'à ce que le mélange soit sec. Ajoutez la coriandre fraîche et remuez.","Mélangez 1 cuillère à soupe de farine avec juste assez d'eau pour obtenir une pâte fluide.","Étalez la pâte sur une planche farinée. Placez 2 cuillères à soupe du mélange de bœuf au centre de la pâte et repliez. Scellez les bords avec la pâte de farine et d'eau.","Chauffez l'huile de friture et faites frire les samosas jusqu'à ce qu'ils soient dorés."],
["Vous pouvez utiliser des feuilles de pâte pour rouleaux impériaux ou de la pâte filo à la place de la pâte pour rouleaux de printemps si vous le souhaitez.","Pour une version moins grasse, vous pouvez cuire les samosas au four sur une plaque graissée au lieu de les frire.","Pour varier, remplacez le bœuf par de la dinde hachée."],
["1/2 viande","1 féculent","1/2 matière grasse"]))
o.append(R(2775,"Curry d'ananas et de poivrons",
"Le curry d'ananas et de poivrons est un savoureux accompagnement pauvre en sodium de Rupa, diététicienne DaVita du New Jersey.",
"4","2/3 tasse",
["2 tasses de poivron vert","1/2 tasse d'oignon rouge","1 cuillère à soupe de coriandre fraîche","5 tomates cerises","1 cuillère à soupe de gingembre frais","2 cuillères à soupe d'huile végétale","1/2 tasse de morceaux d'ananas en conserve dans leur jus","1 cuillère à café de poudre de curry","1/2 cuillère à soupe de jus de citron"],
["Hachez le poivron, l'oignon et la coriandre. Coupez les tomates cerises en deux. Râpez le gingembre.","Chauffez l'huile et, lorsqu'elle est chaude, ajoutez le gingembre et l'oignon rouge. Faites cuire jusqu'à ce que l'oignon soit translucide.","Faites cuire les poivrons au micro-ondes à puissance maximale pendant 6 minutes. Ajoutez les poivrons au mélange d'oignon. Couvrez la poêle et faites cuire à feu doux pendant 10 minutes, en remuant pour éviter que les poivrons ne brûlent.","Ajoutez les morceaux d'ananas et laissez mijoter 2 minutes. Ajoutez la poudre de curry et la coriandre. Retournez les légumes une fois et laissez mijoter à feu doux pendant 2 minutes.","Garnissez de tomates cerises et de jus de citron avant de servir."],
["Servez le curry avec du pain ou du riz."],
["1-1/2 légume, teneur moyenne en potassium","1 matière grasse"]))
o.append(R(2778,"Pot-au-feu de poulet aux pâtes (Chicken pot pie)",
"Le « chicken pot pie » est une recette classique adaptée aux reins qui reviendra plus d'une fois sur votre table.",
"8","2 tasses",
["2 livres de blancs de poulet désossés et sans peau","12 tasses d'eau","1/2 cuillère à café de thym séché","1/4 cuillère à café de poivre noir","2 tasses de pommes de terre, pelées et coupées en petits dés","1-1/2 tasse de carottes, en rondelles","1 tasse de céleri, en dés","1 tasse d'oignon, en dés","2 cuillères à soupe de persil frais, haché","12 onces de pâtes farfalle"],
["Dans une grande casserole, mettez le poulet, l'eau et les assaisonnements. Portez à ébullition.","Réduisez le feu et laissez mijoter 45 minutes.","Placez les pommes de terre en dés dans une grande casserole d'eau à température ambiante et portez à ébullition. Retirez du feu, égouttez l'eau et ajoutez de l'eau fraîche à température ambiante. Portez à ébullition et faites cuire 10 minutes. Égouttez et réservez.","Retirez le poulet de la casserole et réservez-le. Écumez la graisse du bouillon.","Ajoutez les carottes, le céleri et l'oignon au bouillon et portez à ébullition. Faites cuire 5 minutes.","Incorporez les pommes de terre bouillies, le persil et les pâtes en forme de nœuds et faites bouillir 14 minutes ou jusqu'à ce que les pâtes soient tendres.","Coupez le poulet en morceaux et incorporez-le au mélange ; faites bien chauffer et servez."],
["Les pâtes farfalle sont aussi appelées « pot pie bows » (nœuds papillon pour pot-au-feu).","Les pommes de terre sont cuites deux fois pour éliminer une partie du potassium. Si vous ne suivez pas un régime pauvre en potassium, vous pouvez omettre cette étape.","Congelez les restes en portions individuelles pour un repas rapide plus tard.","Vous pouvez réduire le poulet à 1 livre si vous suivez un régime plus pauvre en protéines."],
["3-1/2 viande","2 féculent","2 légume, faible et moyenne teneur en potassium"]))
o.append(R(2779,"Pain à l'ananas",
"L'ananas broyé et les cerises au marasquin sont les ingrédients vedettes de ce délicieux pain à l'ananas tout simple.",
"15","1 tranche",
["1/3 tasse de beurre non salé","1 tasse d'ananas broyé dans son jus","6 cerises au marasquin","1/3 tasse de sucre","2 gros œufs","2-1/4 tasses de farine tout usage","1 cuillère à soupe de levure chimique"],
["Sortez le beurre pour qu'il ramollisse. Égouttez l'ananas. Hachez les cerises.","Au batteur, battez le sucre et le beurre jusqu'à ce que le mélange soit léger et mousseux. Ajoutez les œufs et mélangez bien.","Mélangez la farine et la levure chimique.","Combinez les mélanges de sucre et de farine et mélangez. Ajoutez l'ananas et les cerises et mélangez. Versez dans un moule graissé de 9 x 5 pouces. Faites cuire à 350° F pendant 1 heure.","Laissez refroidir 10 minutes, puis démoulez le pain et transférez-le sur une grille pour finir de refroidir. Coupez en 15 tranches."],
["Préparez des pains supplémentaires et congelez-les jusqu'au moment de les partager ou de les savourer.","Pour réduire les glucides, utilisez un substitut de sucre granulé."],
["1 féculent","1/2 calorie élevée","1/2 matière grasse"]))
o.append(R(2781,"Salade de trois baies au fromage cottage",
"Une bonne portion d'aliments contenant des antioxydants peut agir comme un bouclier protecteur invisible dans votre organisme ! Et si vous le faites régulièrement, dans le cadre d'un plan alimentaire judicieux, les bienfaits pour votre santé seront bien réels. Michelle K., de Californie, rend cela facile et délicieux avec sa recette adaptée aux reins, la salade de trois baies au fromage cottage.",
"4","1/2 tasse de fromage cottage et 1 tasse de mélange de baies",
["2 tasses de fraises fraîches","1 tasse de mûres fraîches","1 tasse de bleuets frais","1/4 tasse de jus de citron","2 tasses de fromage cottage à 1 % de matières grasses","1/8 cuillère à café de cannelle"],
["Lavez bien toutes les baies.","Coupez les fraises en tranches et mélangez-les avec les autres baies dans un bol.","Ajoutez le jus de citron.","Placez le fromage cottage dans une assiette ou un bol de service, puis garnissez de baies.","Saupoudrez de cannelle moulue (facultatif)."],
["Les baies sont une excellente source d'antioxydants. Les citrons sont riches en vitamine C et sont aussi une bonne source d'antioxydants. Les antioxydants aident à neutraliser les radicaux libres dans l'organisme et à maintenir les cellules en bonne santé."],
["2 viande","1 fruit, faible teneur en potassium"]))
o.append(R(2783,"Pâtes épicées au citron",
"Ajoutez du piquant à votre régime rénal avec la recette adaptée aux reins de pâtes épicées au citron.",
"2","2/3 tasse",
["2 cuillères à café de beurre","1/4 tasse d'oignon","1/4 tasse de céleri","1/4 tasse de poivron vert","3/4 tasse de pâtes de blé entier cuites, chaudes","2 cuillères à soupe de jus de citron frais","1 cuillère à café de zeste de citron","1 cuillère à café d'assaisonnement oignon et herbes Mrs. Dash®"],
["Hachez l'oignon, le céleri et le poivron.","Faites fondre le beurre dans une poêle antiadhésive et faites sauter l'oignon, le céleri et le poivron vert. Incorporez aux pâtes chaudes.","Mélangez le jus de citron, le zeste de citron et l'assaisonnement aux herbes Mrs. Dash®. Ajoutez aux pâtes chaudes et mélangez. Servez."],
["Utilisez les pâtes de votre choix. Faites-les cuire selon les instructions de l'emballage, sans sel."],
["1 féculent","1 légume, faible teneur en potassium","1/2 matière grasse"]))
json.dump(o,open('/mnt/c/WSL/davita/translations/out_xfr5_part1.json','w'),ensure_ascii=False)
